lemma induce_degree_eq_of_iso (f : G ≃g H) {s : Set V} {t : Set W}
    (hbij : Set.BijOn (f : V → W) s t) (a : s)
    (i₁ : Fintype ((G.induce s).neighborSet a))
    (i₂ : Fintype ((H.induce t).neighborSet ⟨f a.val, hbij.mapsTo a.2⟩)) :
    @SimpleGraph.degree _ (H.induce t) ⟨f a.val, hbij.mapsTo a.2⟩ i₂
      = @SimpleGraph.degree _ (G.induce s) a i₁

private lemma tT_ne_tT {i j : Fin n} {s t : Bool} {l m : List Bool}
    (h₁ : TValid x n (.treeV i s l)) (h₂ : TValid x n (.treeV j t m))
    (hne : ¬ (i = j ∧ s = t ∧ l = m)) : tT x i s l h₁ ≠ tT x j t m h₂

private lemma tT_ne_of_len {i j : Fin n} {s t : Bool} {l m : List Bool}
    (h₁ : TValid x n (.treeV i s l)) (h₂ : TValid x n (.treeV j t m))
    (hlen : l.length ≠ m.length) : tT x i s l h₁ ≠ tT x j t m h₂

lemma treeV_isDeg3 {i : Fin n} {s : Bool} {l : List Bool}
    (h : TValid x n (.treeV i s l)) (hd : l.length + 1 < x (i : ℕ)) :
    IsDeg3 (TTree x n) (tT x i s l h)

lemma treeV_isLeaf {i : Fin n} {s : Bool} {l : List Bool}
    (h : TValid x n (.treeV i s l)) (hd : l.length + 1 = x (i : ℕ)) :
    IsLeaf (TTree x n) (tT x i s l h)

lemma reachable_tP_of_treeV {i : Fin n} {s : Bool} {l : List Bool}
    (h : TValid x n (.treeV i s l)) :
    (TTree x n).Reachable (tT x i s l h) (tP x i)

lemma isBridge_in {i : Fin n} {s : Bool} {b : Bool} {m : List Bool}
    (h1 : TValid x n (TV.treeV i s (b :: m))) (h2 : TValid x n (TV.treeV i s m)) :
    (TTree x n).IsBridge s(tT x i s (b :: m) h1, tT x i s m h2)

lemma isBridge_in' {i : Fin n} {s : Bool} {b : Bool} {m : List Bool}
    (h1 : TValid x n (TV.treeV i s (b :: m))) (h2 : TValid x n (TV.treeV i s m)) :
    (TTree x n).IsBridge s(tT x i s m h2, tT x i s (b :: m) h1)

